Schueler s1 = new Schueler();
s1.Name = "Lena";
s1.Note = 2;

Schueler s2 = new Schueler();
s2.Name = "Jonas";
s2.Note = 4;

Console.WriteLine($"{s1.Name} hat einen {s1.Note}er.");
Console.WriteLine($"{s2.Name} hat einen {s2.Note}er.");
// Ausgabe:
// Lena hat einen 2er.
// Jonas hat einen 4er.

class Schueler
{
    public string Name = "";
    public int Note;
}

Konto konto = new Konto();
konto.Inhaber = "Mia";
konto.Einzahlen(50);
konto.Einzahlen(20);
konto.Abheben(30);
konto.Ausgeben();
// Ausgabe: Mia hat 40 Euro.

class Konto
{
    public string Inhaber = "";
    public int Guthaben;

    public void Einzahlen(int betrag)
    {
        Guthaben = Guthaben + betrag;
    }

    public void Abheben(int betrag)
    {
        if (betrag <= Guthaben)
        {
            Guthaben = Guthaben - betrag;
        }
        else
        {
            Console.WriteLine("Nicht genug Geld!");
        }
    }

    public void Ausgeben()
    {
        Console.WriteLine($"{Inhaber} hat {Guthaben} Euro.");
    }
}

Schueler a = new Schueler();
a.Name = "Lena";

Schueler b = a;      // kein neues Objekt, nur ein zweiter Verweis!
b.Name = "Sara";

Console.WriteLine(a.Name);
// Ausgabe: Sara

class Schueler
{
    public string Name = "";
}

